    def __init__(self, task_id: int = 2004):
        self.task_id = task_id

    def execute_stage_one(self, payload: dict) -> bool:
        """Executes primary phase of processing."""
        return bool(payload.get("enabled", True))

    def execute_stage_two(self, metric: float) -> float:
        """Computes transformed metric score."""
        return metric * 1.4 + 2004

